export function build(manim) {
 const {Scene,Line,Ellipse,Text,Create,FadeIn,Transform,Dot,TEAL,YELLOW,WHITE}=manim;
 const scene=new Scene();
 const lens=Ellipse({width:0.45,height:3.5,color:TEAL});
 const sensor=Line([3,-2,0],[3,2,0],{color:WHITE});
 const label=Text("Sensor",{color:WHITE}).scale(0.5).move_to([3,-2.5,0]);
 const top=Line([-4,0,0],[0,1.4,0],{color:YELLOW});
 const bottom=Line([-4,0,0],[0,-1.4,0],{color:YELLOW});
 const out1=Line([0,1.4,0],[3,-0.7,0],{color:YELLOW});
 const out2=Line([0,-1.4,0],[3,0.7,0],{color:YELLOW});
 scene.play(Create(lens),Create(sensor),FadeIn(label),{run_time:1});
 scene.play(Create(top),Create(bottom),{run_time:1});
 scene.play(Create(out1),Create(out2),{run_time:1.5});
 scene.wait(1);
 scene.play(Transform(out1,Line([0,1.4,0],[3,0,0],{color:YELLOW})),Transform(out2,Line([0,-1.4,0],[3,0,0],{color:YELLOW})),{run_time:2});
 scene.play(FadeIn(Dot({point:[3,0,0],radius:0.1,color:TEAL})),{run_time:1});
 scene.wait(1);
 return scene;
}
